/* Real Chromium against production bundle; synthetic examples generated by real APIs. */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),output=process.argv[2],fixturePath=process.argv[3];
if(!output||fs.existsSync(output)||!fixturePath)throw Error('NEW output path and fixture required');
const fixture=JSON.parse(fs.readFileSync(fixturePath));const {chromium}=require(process.env.PLAYWRIGHT_MODULE_DIR+'/playwright');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const started=performance.now(),results=[],errors=[],external=[],calls=[];
 const browser=await chromium.launch({headless:true,executablePath:process.env.BROWSER_EXECUTABLE});const context=await browser.newContext({viewport:{width:1440,height:1050}});const page=await context.newPage();page.setDefaultTimeout(6500);page.on('pageerror',e=>errors.push(e.message));
 let control={};const first=fixture.datasets[0],pdf=fixture.datasets[1],mainCandidate=first.responses['/candidates'].candidates[0];
 const safeJob=(ds,state)=>({...ds.job,state,events:state==='completed'?ds.job.events:[],attempt:state==='queued'?0:1,...(state==='failed'?{error_code:'workflow_internal_failure',error_category:'RETRYABLE'}:{error_code:null,error_category:null})});
 await page.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());
  if(u.origin!=='http://127.0.0.1:4173'){external.push(u.origin);return route.abort();}
  const reply=(body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
  if(u.pathname.startsWith('/api/')){calls.push({path:u.pathname,method:req.method(),headers:req.headers()});
   if(u.pathname==='/api/auth/status')return reply({provider_available:true,remote_enabled:false});
   if(u.pathname==='/api/auth/me')return control.anonymous?reply({},401):reply({user_id:'synthetic-reviewer',institution_id:'A',institution_name:'합성 연구지원기관',role:control.role||'manager',institution_admin:true,csrf_token:'synthetic-csrf'});
   if(u.pathname==='/api/documents'){const docs=structuredClone(fixture.documents);if(control.foreignList)docs[0].institution_id='B';if(control.deregister)docs[0].registered=false;if(control.inactive)docs[0].active=false;return reply(docs);}
   const match=u.pathname.match(/^\/api\/documents\/([^/]+)\/versions\/([^/]+)(.*)$/);if(!match)return reply({},404);
   const ds=fixture.datasets.find(x=>x.document.document_id===match[1]&&x.document.id===match[2]);if(!ds){const doc=fixture.documents.find(d=>d.document_id===match[1]&&d.id===match[2]);return reply(doc||{},doc?200:404);}
   const tail=match[3];if(!tail){if(control.deregister)return reply({},404);return reply({...ds.document,active:control.inactive?false:true});}
   if(tail==='/original'){await delay(control.pdfDelay||0);return route.fulfill({status:200,contentType:'application/pdf',body:Buffer.from(ds.original_pdf_base64,'base64')});}
   if(tail.includes('/chunks/')){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');const ref=req.postDataJSON();let data=structuredClone(ds.resolved[ref.chunk_id]);if(control.badResolve)data.evidence.organization_id='B';return reply(data);}
   if(!tail.startsWith('/workflow'))return reply({},404);
   if(control.forbiddenAll)return reply({},403);
   const suffix=tail.slice('/workflow'.length);if(suffix==='/jobs'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');assert.deepEqual(req.postDataJSON(),{});control.posts=(control.posts||0)+1;await delay(control.submitDelay||0);return reply(safeJob(ds,control.enqueueFailed?'failed':'queued'),202);}
   if(suffix.endsWith('/retry')){control.retries=(control.retries||0)+1;return reply(safeJob(ds,'queued'),202);}
   if(suffix.endsWith('/cancel')){control.cancels=(control.cancels||0)+1;return reply(safeJob(ds,'cancelled'));}
   if(suffix.startsWith('/jobs/')){control.polls=(control.polls||0)+1;return reply(safeJob(ds,control.neverComplete?'processing':control.polls<2?'processing':'completed'));}
   if(suffix==='/candidates'&&control.workflowError){if(control.workflowError==='network')return route.abort();return reply({},control.workflowError);}
   if(control.late&&ds===first&&suffix==='/candidates')await delay(1200);
   let data=structuredClone(ds.responses[suffix+u.search]||ds.responses[suffix]);if(!data)return reply({},404);
   if(control.bigGraph&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence')){const c=data.candidates[0];c.steps=[...c.steps,...Array.from({length:96},(_,i)=>({...structuredClone(c.steps[i%4]),id:'stress_'+i}))];}
   if(control.empty&&suffix==='/candidates')data.candidates=[];
   if(control.unsafe)data.semantic_verification='VERIFIED';
   if(control.mixedGeneration&&suffix.startsWith('/form-links'))data.generation_id='another-generation';
   if(control.foreignEvidence&&suffix.endsWith('/evidence'))data.evidence_refs[0].organization_id='B';
   if(control.unrenderable&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].edges[0].target='unknown-step';
   try{return await reply(data);}catch{return;}
  }
  const dist=path.join(root,'apps/web/dist'),file=path.resolve(dist,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(u.pathname==='/favicon.ico')return route.fulfill({status:204,body:''});if(!file.startsWith(dist+path.sep)||!fs.existsSync(file))return route.abort();return route.fulfill({body:fs.readFileSync(file),contentType:file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html'});
 });
 let bootId=0;
 async function boot(options={},ready=true){control={...options};await page.setViewportSize({width:1440,height:1050});await page.goto('http://127.0.0.1:4173/?case='+(++bootId)+'#/workflows');if(ready)await page.locator('.wf-original-quote').waitFor();}
 async function check(name,fn){try{await fn();results.push({name,status:'PASS'});console.log('PASS '+name);}catch(e){results.push({name,status:'FAIL',error:e.message});console.log('FAIL '+name+': '+e.message);}}
 async function step(index){await page.locator('.wf-map-node').nth(index).click();await page.locator('.wf-original-quote').filter({hasText:mainCandidate.steps[index].label.evidence[0].quote}).waitFor();}
 try{
 await check('manager candidate/detail API and unverified labels',async()=>{await boot();assert.equal(await page.locator('.wf-map-node').count(),4);assert.match(await page.locator('.connection-notice').innerText(),/관리자 검토 전용/);assert.match(await page.locator('.wf-trust').innerText(),/내용 검토 필요/);assert.match(await page.locator('.wf-trust details').textContent(),/NOT_VERIFIED.*NOT_REQUESTED/);assert.equal(await page.getByRole('button',{name:/승인|공식 게시/}).count(),0);});
 await check('exact saved edges only; conditions and return relation',async()=>{await boot();assert.equal(await page.locator('.react-flow__edge').count(),mainCandidate.edges.length);await page.getByText(/조건·분기·반복 및 관계 목록/).click();assert.match(await page.locator('.wf-relationships').innerText(),/보완.*후보/);assert.match(await page.locator('.wf-relationships').innerText(),/1단계/);});
 await check('node selection resolves canonical evidence and XML anchor',async()=>{await boot();await step(2);assert.match(await page.locator('.wf-original-quote').innerText(),/누락된 경우/);await page.getByText('원문 위치 상세',{exact:true}).click();assert.match(await page.locator('.wf-anchor').innerText(),/Contents\/section0.xml/);assert.match(await page.locator('.wf-limitation').innerText(),/페이지.*확인되지/);});
 await check('CANDIDATES file is not confirmed required',async()=>{await boot();assert.match(await page.locator('.wf-form').innerText(),/연결 후보/);assert.match(await page.locator('.wf-form').innerText(),/필수 여부 미확정/);});
 await check('UNLINKED no registered form',async()=>{await boot();await step(1);assert.match(await page.locator('.wf-form').innerText(),/미등록 · 미연결/);});
 await check('AMBIGUOUS multiple form files retained',async()=>{await boot();await step(3);assert.match(await page.locator('.wf-form').innerText(),/동명·유사/);assert.equal(await page.locator('.wf-form li').count(),2);});
 await check('review count/details and source claims shown separately',async()=>{await boot();await page.getByText(/전체 검토 항목/).click();assert.ok(await page.locator('.wf-issue-list li').count()>0);assert.ok(await page.getByRole('heading',{name:'추출 주장',exact:true}).isVisible());assert.ok(await page.getByRole('heading',{name:'근거 원문 텍스트',exact:true}).isVisible());});
 await check('keyboard alternative step list and visible focus',async()=>{await boot();await page.getByRole('button',{name:'단계 목록',exact:true}).click();const button=page.locator('.wf-step-list button').nth(1);await button.focus();assert.equal(await button.evaluate(n=>getComputedStyle(n).outlineWidth),'3px');await page.keyboard.press('Enter');assert.equal(await button.getAttribute('aria-pressed'),'true');await page.locator('.wf-original-quote').waitFor();});
 await check('zoom out/in/fit controls work without changing relations',async()=>{await boot();const before=await page.locator('.react-flow__viewport').getAttribute('style');await page.getByRole('button',{name:'지도 확대',exact:true}).click();await page.waitForTimeout(150);assert.notEqual(await page.locator('.react-flow__viewport').getAttribute('style'),before);await page.getByRole('button',{name:'지도 축소',exact:true}).click();await page.getByRole('button',{name:'전체 지도 보기',exact:true}).click();assert.equal(await page.locator('.react-flow__edge').count(),mainCandidate.edges.length);});
 await check('320/375/768/1440 reflow and mobile keyboard tabs',async()=>{await boot();for(const width of [320,375,768,1440]){await page.setViewportSize({width,height:1000});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'overflow at '+width);}await page.setViewportSize({width:375,height:812});await page.getByRole('tab',{name:'지도·단계'}).focus();await page.keyboard.press('ArrowRight');assert.equal(await page.getByRole('tab',{name:'원문 근거'}).getAttribute('aria-selected'),'true');assert.ok(await page.locator('.wf-evidence-pane').isVisible());});
 await check('mobile selected step moves focus to evidence heading',async()=>{await boot();await page.setViewportSize({width:375,height:812});await page.getByRole('button',{name:'단계 목록',exact:true}).click();await page.locator('.wf-step-list button').nth(2).click();await page.locator('.wf-original-quote').waitFor();assert.equal(await page.evaluate(()=>document.activeElement.textContent),'원문 근거 확인');assert.match(await page.locator('.wf-original-quote').innerText(),/누락된 경우/);});
 await check('actual screenshots desktop/mobile map/evidence',async()=>{await boot();const out=path.join(root,process.env.PHASE2E_CAPTURE_DIR||'outputs/phase2e1');fs.mkdirSync(out,{recursive:true});for(const file of ['workflow-desktop.png','workflow-mobile-map.png','workflow-mobile-evidence.png'])if(fs.existsSync(path.join(out,file)))throw Error('new capture path required');await page.screenshot({path:path.join(out,'workflow-desktop.png'),fullPage:true});await page.setViewportSize({width:375,height:812});await page.screenshot({path:path.join(out,'workflow-mobile-map.png'),fullPage:true});await page.getByRole('tab',{name:'원문 근거'}).click();await page.screenshot({path:path.join(out,'workflow-mobile-evidence.png'),fullPage:true});});
 await check('reader has no manager UI or workflow calls',async()=>{const from=calls.length;await boot({role:'reader'},false);await page.getByRole('heading',{name:'관리자 권한이 필요합니다'}).waitFor();assert.equal(calls.slice(from).filter(c=>c.path.includes('/workflow')).length,0);assert.equal(await page.getByRole('link',{name:'업무절차 검토',exact:true}).count(),0);});
 await check('anonymous cannot query protected workflows',async()=>{const from=calls.length;await boot({anonymous:true},false);await page.locator('#login-email').waitFor();assert.equal(calls.slice(from).filter(c=>c.path.includes('/workflow')).length,0);});
 for(const status of [403,409,500,'network'])await check('workflow '+status+' clears candidate/evidence data',async()=>{await boot({workflowError:status},false);await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.wf-map-node').count(),0);assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('401 expires session and unmounts private UI',async()=>{await boot({workflowError:401},false);await page.locator('#login-email').waitFor();assert.equal(await page.locator('.wf-source-select').count(),0);});
 await check('404 and empty result are distinct non-failure states',async()=>{await boot({workflowError:404},false);await page.getByRole('heading',{name:'조회 가능한 업무 후보가 없습니다'}).waitFor();await boot({empty:true},false);await page.getByRole('heading',{name:'조회 가능한 업무 후보가 없습니다'}).waitFor();});
 for(const option of ['foreignList','foreignEvidence','badResolve','unsafe','mixedGeneration'])await check(option+' rejected before source display',async()=>{await boot({[option]:true},false);await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('late document response discarded; PDF anchor and original request',async()=>{await boot({late:true},false);await page.getByLabel('문서',{exact:true}).selectOption(pdf.document.document_id);await page.locator('.wf-evidence-meta').filter({hasText:'광물-접수.pdf'}).waitFor();await page.locator('.wf-original-quote').waitFor();await page.waitForTimeout(1400);assert.match(await page.locator('.wf-evidence-meta').innerText(),/광물-접수.pdf/);await page.getByText('원문 위치 상세',{exact:true}).click();assert.match(await page.locator('.wf-anchor').innerText(),/페이지 1/);await page.getByRole('button',{name:'PDF 원본 준비'}).click();await page.getByRole('link',{name:/PDF 원본 열기/}).waitFor();assert.match(await page.getByRole('link',{name:/PDF 원본 열기/}).getAttribute('href'),/^blob:.*#page=1$/);});
 await check('active version change clears visible candidate',async()=>{await boot();control.inactive=true;await page.waitForTimeout(5500);assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('deregistered document clears visible candidate',async()=>{await boot();control.deregister=true;await page.waitForTimeout(5500);assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('double enqueue submits once with CSRF; polling completes',async()=>{await boot({submitDelay:400});await page.getByRole('button',{name:'추출 작업 요청'}).evaluate(n=>{n.click();n.click();});await page.getByText('처리 완료 · 검토 필요',{exact:true}).waitFor();await page.locator('.wf-original-quote').waitFor();assert.equal(control.posts,1);assert.ok(control.polls>=2);});
 await check('failed retryable job and retry are explicit',async()=>{await boot({enqueueFailed:true});await page.getByRole('button',{name:'추출 작업 요청'}).click();await page.getByRole('button',{name:'실패 작업 재시도'}).click();await page.getByText('처리 완료 · 검토 필요',{exact:true}).waitFor();assert.equal(control.retries,1);});
 await check('processing cancellation calls only existing API',async()=>{await boot({neverComplete:true});await page.getByRole('button',{name:'추출 작업 요청'}).click();await page.getByRole('button',{name:'작업 취소'}).click();await page.getByText('취소됨',{exact:true}).waitFor();assert.equal(control.cancels,1);});
 await check('unrenderable relation retained in separate list',async()=>{await boot({unrenderable:true});await page.getByText(/조건·분기·반복 및 관계 목록/).click();await page.getByText('지도 미표시 관계',{exact:true}).waitFor();assert.equal(await page.locator('.react-flow__edge').count(),mainCandidate.edges.length-1);});
 await check('100-node layout supports controls and accessible alternative',async()=>{await boot({bigGraph:true});assert.equal(await page.locator('.wf-map-node').count(),100);await page.getByRole('button',{name:'지도 확대',exact:true}).click();await page.getByRole('button',{name:'단계 목록',exact:true}).click();assert.equal(await page.locator('.wf-step-list button').count(),100);});
 await check('late enqueue acknowledgement cannot replace new document',async()=>{await boot({submitDelay:1300});await page.getByRole('button',{name:'추출 작업 요청'}).click();await page.getByLabel('문서',{exact:true}).selectOption(pdf.document.document_id);await page.locator('.wf-original-quote').waitFor();await page.waitForTimeout(1500);assert.match(await page.locator('.wf-evidence-meta').innerText(),/광물-접수.pdf/);assert.equal(await page.locator('.wf-job').count(),0);});
 await check('late PDF response discarded after document switch',async()=>{await boot({pdfDelay:1200});await page.getByLabel('문서',{exact:true}).selectOption(pdf.document.document_id);await page.locator('.wf-original-quote').waitFor();await page.evaluate(()=>{const original=URL.createObjectURL;window.createdPdfUrls=0;URL.createObjectURL=function(...args){window.createdPdfUrls++;return original.apply(this,args);};});await page.getByRole('button',{name:'PDF 원본 준비',exact:true}).click();await page.getByLabel('문서',{exact:true}).selectOption(first.document.document_id);await page.locator('.wf-original-quote').waitFor();await page.waitForTimeout(1400);assert.equal(await page.evaluate(()=>window.createdPdfUrls),0);assert.equal(await page.getByRole('link',{name:/PDF 원본 열기/}).count(),0);});
 await check('workflow-level review issue remains visible for selected step',async()=>{await boot();assert.match(await page.locator('.wf-evidence-pane .wf-issue-list').innerText(),/결정적 원문 후보/);});
 await check('no browser exceptions or external destinations',async()=>{assert.deepEqual(errors,[]);assert.deepEqual(external,[]);});
 }finally{await browser.close();}
 const report={scope:'Phase2E-1 production Chromium UI; intercepted local API with REAL synthetic backend-generated shapes; no live provider',results,counts:{PASS:results.filter(x=>x.status==='PASS').length,FAIL:results.filter(x=>x.status==='FAIL').length},seconds:(performance.now()-started)/1000,unexpected_external_requests:external,js_errors:errors,fixture:fixturePath,not_run:['screen reader','native PDF viewer page rendering','Hancom visual pages','real Supabase','actual LLM']};fs.writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));if(report.counts.FAIL)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
